SELECT t.tgname, t.tgenabled FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relname='case_entries' AND NOT t.tgisinternal ORDER BY t.tgname; SELECT slug, length(mrn_hash_salt) AS salt_len FROM tenants WHERE slug='global-community'; SELECT proname FROM pg_proc WHERE proname IN ('debug_swarm_introspect','debug_wave2_introspect','debug_policies_full','debug_exp_tombstone');
